import { test } from "@e2e/fixtures";
import * as flows from "@e2e/flows";

test.describe("Chat quick-reply buttons", () => {
  // Inspect mode: the chat flows gate each send on "Agent turn ended".
  test.use({
    inspectorOptions: {
      inspectMode: true,
    },
  });

  test("Clicking Yes on add-contact confirmation advances the flow", async ({ inspectorPage }) => {
    await flows.chat.sendMessageAndAssertBotReplies(inspectorPage, "Add @tester", {
      expectedBotMessageCount: 2,
    });
    await flows.chat.sendMessageAndAssert(inspectorPage, "Tester A");
    await flows.chat.clickBotButtonAndAssertReply(inspectorPage, "Yes");
  });
});
